//! Decimal / money vectors generated by the real TS decimal.js and Prisma Decimal code.

use std::str::FromStr;

use pg_types::{DecimalJs, Money4, RoundingMode};
use rust_decimal::Decimal;
use serde::Deserialize;

const MONEY: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../tests/golden-vectors/money-decimal.json"
));

#[derive(Deserialize)]
struct File {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    id: String,
    kind: String,
    #[serde(default)]
    input: Option<String>,
    #[serde(default)]
    decimal_to_string: Option<String>,
    #[serde(default)]
    to_fixed4: Option<String>,
    #[serde(default)]
    prisma_json: Option<PrismaJson>,
    #[serde(default)]
    mode: Option<String>,
    #[serde(default)]
    value: Option<String>,
    #[serde(default)]
    amount: Option<String>,
    #[serde(default)]
    percentage_rate: Option<String>,
    #[serde(default)]
    rounded: Option<String>,
    #[serde(default)]
    commission: Option<String>,
    #[serde(default)]
    input_mode: Option<String>,
    #[serde(default)]
    resolved_mode: Option<String>,
}

#[derive(Deserialize)]
struct PrismaJson {
    v: String,
}

fn parse_decimal(input: &str) -> Decimal {
    let mut value = if input.contains('e') || input.contains('E') {
        Decimal::from_scientific(input).expect(input)
    } else {
        Decimal::from_str(input).expect(input)
    };
    // decimal.js preserves the sign of negative zero; rust_decimal parses "-0" as positive zero.
    if input.starts_with('-') && value.is_zero() {
        value.set_sign_negative(true);
    }
    value
}

#[test]
fn decimal_vectors_match() {
    let file: File = serde_json::from_str(MONEY).expect("money vectors");
    let mut decimals = 0;
    for case in file.cases.iter().filter(|case| case.kind == "decimal") {
        decimals += 1;
        let input = case.input.as_deref().expect("input");
        let decimal = parse_decimal(input);
        let prisma = case.prisma_json.as_ref().expect("prismaJson");
        assert_eq!(DecimalJs(decimal).to_string(), prisma.v, "{}", case.id);
        assert_eq!(
            Money4(decimal).to_string(),
            case.to_fixed4.as_deref().expect("toFixed4"),
            "{}",
            case.id
        );
        let to_string = case.decimal_to_string.as_deref().expect("decimalToString");
        if input.starts_with('-') && decimal.is_zero() {
            assert_eq!(to_string, "0");
            assert_eq!(prisma.v, "-0");
        } else {
            assert_eq!(to_string, prisma.v, "{}", case.id);
        }
    }
    assert_eq!(decimals, 30);
}

#[test]
fn rounding_and_commission_vectors_match() {
    let file: File = serde_json::from_str(MONEY).expect("money vectors");
    let mut count = 0;
    for case in file
        .cases
        .iter()
        .filter(|case| case.kind == "rounding" || case.kind == "commission")
    {
        count += 1;
        let mode = RoundingMode::parse(case.mode.as_deref().expect("mode")).expect("mode");
        let value = match case.kind.as_str() {
            "rounding" => parse_decimal(case.value.as_deref().expect("value")),
            "commission" => {
                let amount = parse_decimal(case.amount.as_deref().expect("amount"));
                let rate = parse_decimal(case.percentage_rate.as_deref().expect("rate"));
                amount.checked_mul(rate).expect("commission multiplication")
            }
            _ => unreachable!(),
        };
        let mut rounded = mode.apply(value);
        rounded.rescale(4);
        let expected = case
            .rounded
            .as_deref()
            .or(case.commission.as_deref())
            .expect("expected");
        assert_eq!(rounded.to_string(), expected, "{}", case.id);
    }
    assert_eq!(count, 28);
}

#[test]
fn ts_rounding_aliases_and_fallback() {
    let file: File = serde_json::from_str(MONEY).expect("money vectors");
    for case in file
        .cases
        .iter()
        .filter(|case| case.kind == "roundingAlias")
    {
        let input = case.input_mode.as_deref().expect("inputMode");
        let expected = case.resolved_mode.as_deref().expect("resolvedMode");
        let mode = RoundingMode::parse_or_default(input);
        assert_eq!(format!("{mode:?}"), camel(expected), "{}", case.id);
        let value = parse_decimal(case.value.as_deref().expect("value"));
        let mut rounded = mode.apply(value);
        rounded.rescale(4);
        assert_eq!(
            rounded.to_string(),
            case.rounded.as_deref().expect("rounded"),
            "{}",
            case.id
        );
    }
}

fn camel(mode: &str) -> String {
    match mode {
        "HALF_UP" => "HalfUp".to_owned(),
        "HALF_EVEN" => "HalfEven".to_owned(),
        "HALF_DOWN" => "HalfDown".to_owned(),
        "UP" => "Up".to_owned(),
        "DOWN" => "Down".to_owned(),
        "CEILING" => "Ceiling".to_owned(),
        "FLOOR" => "Floor".to_owned(),
        other => other.to_owned(),
    }
}
